// date (a claim dated before it rounds half up, on or after it half to even; blank for the sheet's today), the
// period numbering from-date (while the sheet's today is on or after it, a claim opened is numbered within its
// period; blank for off), the grace days (a today change closes each open period whose to-date plus these days
// is before the new today; blank for off; not dated), the permission matrix (for each action, the roles that may take it, comma separated;
// blank keeps the standing rule; not dated), the entry date (while set, the default date of a new claim in
// place of the sheet's today; blank for off; not dated), the fiscal start month (the month, 1 to 12, a fiscal year
// starts in; 1 unless set; not dated), and
// the policy version (every change to the rounding mode, the floor, the cap, the terms, the late percent or the
// clerk limit makes a new one, numbered from 1) and, once shown, the versions oldest first, each as
// <version> <from-date or start> <key>=<value> <count of the sheet's claims whose policy version it is>, and
// the role each user name has on the sheet (clerk unless given another), and the delegations of the steward role
// (a steward gives a user the role from a date to a date, inclusive, by the sheet's today).
@Component({
  selector: 'app-settings',
  template: `
    <section aria-label="Settings" data-testid="settings">
      <h2>Settings</h2>
      <p>Policy version: <strong data-testid="policy-version">{{ session.policyVersion() }}</strong></p>
      <button type="button" data-testid="policy-show" (click)="policyShown.set(true)">Show policy versions</button>
      @if (policyShown()) {
        <ol aria-label="Policy versions" data-testid="policy-lines">
          @for (line of policyLines(); track $index) {
            <li data-testid="policy-line">{{ line }}</li>
          }
        </ol>
      }
      <form (submit)="save($event)" data-testid="settings-form">
        <label for="setting-clerk-limit">Clerk limit (blank for none)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitTouched.set(true); error.set(null)"
          (focus)="focused.set('limit')"
        />
        <label for="setting-clerk-limit-from">Clerk limit from (YYYY-MM-DD; blank for the sheet's today)</label>
        <input
          id="setting-clerk-limit-from"
          data-testid="setting-clerk-limit-from"
          [value]="fromOf('clerk-limit')"
        <button type="submit" data-testid="delegate-submit" [disabled]="delegating()">Delegate steward role</button>
        @if (delegateError(); as err) {
          <p role="alert" data-testid="delegate-error">{{ err }}</p>
        }
      </form>
      <ul data-testid="delegate-list" aria-label="Delegations">
        @for (d of roles.delegations(); track d.id) {
          <li data-testid="delegate-line">{{ d.delegator }} delegated steward to {{ d.user }} from {{ d.from }} to {{ d.to }}</li>
        }
      </ul>
    </section>
  `,
})
export class SettingsPanel {
  protected readonly session = inject(Session);
  protected readonly roles = inject(Roles);
  private readonly pools = inject(Pools);
  private readonly rates = inject(Rates);
  private readonly claims = inject(Claims);
  /** Whether the policy versions are listed. */
  protected readonly policyShown = signal(false);
  /** The policy versions, oldest first, each with the number of the sheet's claims whose policy version it is. */
  protected readonly policyLines = computed(() => {
    const counts = new Map<number, number>();
    for (const c of this.claims.claims()) {
      const n = this.session.policyVersionOn(c.date);
      counts.set(n, (counts.get(n) ?? 0) + 1);
    }
    return this.session
      .policyVersions()
      .map((v, i) => `${i + 1} ${v.from ?? 'start'} ${v.key}=${v.value ?? ''} ${counts.get(i + 1) ?? 0}`);
  });
  protected readonly roleNames = ROLES.join(' or ');
  protected readonly limit = signal('');
  protected readonly limitTouched = signal(false);
  protected readonly floor = signal('');
  protected readonly floorTouched = signal(false);
  protected readonly rounding = signal('');
  protected readonly roundingTouched = signal(false);
  protected readonly cap = signal('');
  protected readonly capTouched = signal(false);
  protected readonly proofThreshold = signal('');
  protected readonly proofThresholdTouched = signal(false);
  protected readonly noteThreshold = signal('');
  protected readonly noteThresholdTouched = signal(false);
  protected readonly reviewThreshold = signal('');
  protected readonly reviewThresholdTouched = signal(false);
  protected readonly terms = signal('');
  protected readonly termsTouched = signal(false);
  protected readonly grades = this.session.grades;
  /** What is typed for each grade's terms, and the grades typed into since the last save. */
  protected readonly gradeTerms = signal<Record<string, string>>({});
  protected readonly gradeTermsTouched = signal<ReadonlySet<string>>(new Set());
  /** What is typed for each grade's clerk limit, and the grades typed into since the last save. */
  protected readonly gradeClerkLimit = signal<Record<string, string>>({});
  protected readonly gradeClerkLimitTouched = signal<ReadonlySet<string>>(new Set());
  /** What is typed for each grade's proof threshold, and the grades typed into since the last save. */
  protected readonly gradeProofThreshold = signal<Record<string, string>>({});
  protected readonly gradeProofThresholdTouched = signal<ReadonlySet<string>>(new Set());
  /** What is typed for each grade's grace days, and the grades typed into since the last save. */
  protected readonly gradeGrace = signal<Record<string, string>>({});
/** Download these lines as a CSV file of this name, each line ended by a line feed. */
export function download(lines: string[][], name: string): void {
  const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** A CSV field: wrapped in double quotes, with quotes inside doubled, when it holds a comma, a
 *  quote or a line break. */
function csvField(v: string): string {
  return /[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
}
        ]);
      }
    }
    download(lines, 'claims.csv');
  }

  /** Download the period figures as CSV: people in list order, each with the periods in the order
   *  added, with the figure and carried amount as their rows show them. */
  protected async exportPeriods(): Promise<void> {
    await this.session.loaded();
    const periods = [...this.periods.periods()].sort((a, b) => a.id - b.id);
    const lines = [['person', 'period', 'figure', 'carried']];
    for (const p of this.people.people()) {
      for (const period of periods) {
        lines.push([p.name, period.name, this.figures.personPeriodDue(period, p.id), this.figures.personPeriodCarried(period, p.id)]);
      }
    }
    download(lines, 'periods.csv');
  }

  /** Download the person's row as CSV: one line per cell, with the value as the row shows it. */
  protected async exportPerson(p: Person): Promise<void> {
    await this.session.loaded();
    download(
      [
        ['cell', 'value'],
        ['person-name', this.figures.shownName(p)],
        ['person-grade', this.gradeToday(p)],
        ['person-claimed', this.claims.claimed(p.id)],
        ['person-due-total', this.due(p)],
        ['person-statement-count', String(p.statementCount)],
        ['person-overdue-total', this.overdueDue(p)],
        ['person-hold', p.held ? 'yes' : 'no'],
        ['person-retired', p.retired ? 'yes' : 'no'],
        ['person-aliases', p.aliases.join(', ')],
        ['person-score', String(this.figures.score(p))],
      ],
      'person.csv',
    );
  }

